svg.script:
(function () {
  const svg = document.documentElement;
  const NS = "http://www.w3.org/2000/svg";
  const XHTML = "http://www.w3.org/1999/xhtml";

  const articles = [
    {id:"g1", x:3.078, y:90.013}
  ];

  const original = {
    width:"1590",
    height:"725",
    viewBox:"0 0 1590 725"
  };

  const originalBanner = {
    x:"3.078",
    y:"-91.298477",
    width:"1439.238",
    height:"92.063"
  };

  function wrap(id, wrapperId) {
    const element = document.getElementById(id);
    if (!element) return null;

    let wrapper = document.getElementById(wrapperId);
    if (wrapper) return wrapper;

    wrapper = document.createElementNS(NS, "g");
    wrapper.setAttribute("id", wrapperId);

    element.parentNode.insertBefore(wrapper, element);
    wrapper.appendChild(element);

    return wrapper;
  }

  const wrappers = {};

  articles.forEach((a, i) => {
    wrappers[a.id] = wrap(a.id, "mobile-wrapper-" + i);
  });

  wrappers.logo = wrap("g41", "mobile-wrapper-logo");
  wrappers.title = wrap("g2", "mobile-wrapper-title");
  wrappers.subtitle = wrap("g3", "mobile-wrapper-subtitle");
  wrappers.home = wrap("a1", "mobile-wrapper-home");
  wrappers.bannerRect = wrap("rect8", "mobile-wrapper-banner-rect");

  const banner = document.getElementById("rect8");

  function move(wrapper, x, y, scale) {
    if (!wrapper) return;

    scale = scale || 1;

    wrapper.setAttribute(
      "transform",
      "translate(" + x + " " + y + ") scale(" + scale + ")"
    );
  }

  function restoreRectangle(element, values) {
    if (!element) return;

    element.setAttribute("x", values.x);
    element.setAttribute("y", values.y);
    element.setAttribute("width", values.width);
    element.setAttribute("height", values.height);
    element.setAttribute("transform", "scale(1,-1)");
  }

  // ==========================================================
  // CONVERSION DES COORDONNÉES SVG
  // ==========================================================

  function convertPoint(point, sourceElement, targetParent) {
    const sourceMatrix = sourceElement.getCTM();
    const targetMatrix = targetParent.getCTM();

    if (!sourceMatrix || !targetMatrix) {
      throw new Error("Impossible de calculer les coordonnées SVG.");
    }

    const svgPoint = point.matrixTransform(sourceMatrix);

    return svgPoint.matrixTransform(targetMatrix.inverse());
  }

  function getBannerTopInTitleCoordinates() {
    if (!wrappers.bannerRect || !wrappers.title) {
      throw new Error("Bandeau ou titre introuvable.");
    }

    const bannerBounds = wrappers.bannerRect.getBBox();
    const point = svg.createSVGPoint();

    point.x = bannerBounds.x;
    point.y = bannerBounds.y;

    const titleParent = wrappers.title.parentNode;

    const convertedPoint = convertPoint(
      point,
      wrappers.bannerRect,
      titleParent
    );

    return convertedPoint.y;
  }

  // ==========================================================
  // TEXTES ET PANNEAU DE L'ARTICLE
  // ==========================================================

  const articleGroup = document.getElementById("g1");
  const articlePanel = document.getElementById("rect4");

  const articleTitle = document.getElementById("text39");
  const articleText = document.getElementById("text41");
  const articleReference = document.getElementById("text43");
  const articleCopyright = document.getElementById("text38");

  const originalArticleHeight = articlePanel.getAttribute("height");
  const originalArticleWidth = articlePanel.getAttribute("width");
  const originalArticleX = articlePanel.getAttribute("x");

  const originalTitleDisplay = articleTitle.style.display;
  const originalTextDisplay = articleText.style.display;
  const originalReferenceDisplay = articleReference.style.display;
  const originalCopyrightDisplay = articleCopyright
    ? articleCopyright.style.display
    : "";

  const originalTitleContent = articleTitle.textContent;
  const originalArticleContent = articleText.textContent;
  const originalReferenceContent = articleReference.textContent;
  const originalCopyrightContent = articleCopyright
    ? articleCopyright.textContent
    : "";

  let mobileTitleObject = null;
  let mobileTitleContainer = null;

  let mobileTextObject = null;
  let mobileTextContainer = null;

  let mobileReferenceObject = null;
  let mobileReferenceContainer = null;

  let mobileCopyrightObject = null;
  let mobileCopyrightContainer = null;

  let currentMobileWidth = 376;
  let resizeFrame = null;

  function getAvailableWidth() {
    const parent = svg.parentElement;

    const parentWidth = parent
      ? parent.clientWidth
      : 0;

    const viewportWidth =
      document.documentElement.clientWidth ||
      window.innerWidth ||
      376;

    return Math.max(
      280,
      Math.round(parentWidth || viewportWidth)
    );
  }

  function createTextObject(
    id,
    y,
    fontSize,
    lineHeight,
    fontFamily,
    weight,
    italic
  ) {
    const foreignObject = document.createElementNS(
      NS,
      "foreignObject"
    );

    foreignObject.setAttribute("id", id);
    foreignObject.setAttribute("x", "9");
    foreignObject.setAttribute("y", String(y));
    foreignObject.setAttribute("width", "338");
    foreignObject.setAttribute("height", "10000");

    const container = document.createElementNS(XHTML, "div");

    container.style.cssText =
      "box-sizing:border-box;" +
      "width:100%;" +
      "margin:0;" +
      "padding:0;" +
      "font-family:" + fontFamily + ";" +
      "font-size:" + fontSize + "px;" +
      "font-weight:" + weight + ";" +
      "font-style:" + italic + ";" +
      "line-height:" + lineHeight + ";" +
      "color:#333333;" +
      "text-align:justify;" +
      "text-align-last:start;" +
      "white-space:normal;" +
      "overflow-wrap:break-word;" +
      "word-break:normal;";

    foreignObject.appendChild(container);
    articleGroup.appendChild(foreignObject);

    return {
      object: foreignObject,
      container: container
    };
  }

  function createMobileArticleText() {
    if (mobileTitleObject) return;

    const title = createTextObject(
      "mobile-article-title",
      150.82375,
      37,
      1.25,
      "'Leelawadee UI',Arial,sans-serif",
      "bold",
      "normal"
    );

    title.container.textContent =
      originalTitleContent.replace(/\s+/g, " ").trim();

    mobileTitleObject = title.object;
    mobileTitleContainer = title.container;

    const body = createTextObject(
      "mobile-article-text",
      160,
      27,
      1.25,
      "Arial,sans-serif",
      "normal",
      "normal"
    );

    const paragraphs = originalArticleContent
      .replace(/\r/g, "")
      .split(/\n\s*\n/);

    paragraphs.forEach(function (paragraph, index) {
      const content = paragraph.replace(/\s+/g, " ").trim();
      if (!content) return;

      const p = document.createElementNS(XHTML, "p");

      p.textContent = content;
      p.style.margin = index === paragraphs.length - 1
        ? "0"
        : "0 0 12px 0";

      body.container.appendChild(p);
    });

    mobileTextObject = body.object;
    mobileTextContainer = body.container;

    const reference = createTextObject(
      "mobile-article-reference",
      0,
      21.3334,
      1.2,
      "Calibri,Arial,sans-serif",
      "300",
      "italic"
    );

    reference.container.textContent =
      originalReferenceContent.replace(/\s+/g, " ").trim();

    mobileReferenceObject = reference.object;
    mobileReferenceContainer = reference.container;

    const copyright = createTextObject(
      "mobile-article-copyright",
      0,
      21.3334,
      1.25,
      "'Leelawadee UI',Arial,sans-serif",
      "300",
      "normal"
    );

    copyright.container.textContent =
      originalCopyrightContent.replace(/\s+/g, " ").trim();

    copyright.container.style.textAlign = "right";
    copyright.container.style.textAlignLast = "right";

    mobileCopyrightObject = copyright.object;
    mobileCopyrightContainer = copyright.container;

    articleTitle.style.display = "none";
    articleText.style.display = "none";
    articleReference.style.display = "none";

    if (articleCopyright) {
      articleCopyright.style.display = "none";
    }
  }

  function setMobileTextWidth(width) {
    const panelMargin = 14;
    const panelWidth = Math.max(240, width - panelMargin * 2);
    const innerPadding = 10;
    const textWidth = Math.max(210, panelWidth - innerPadding * 2);

    [
      mobileTitleObject,
      mobileTextObject,
      mobileReferenceObject,
      mobileCopyrightObject
    ].forEach(function (element) {
      if (!element) return;

      element.setAttribute("width", String(textWidth));
    });

    [
      mobileTitleContainer,
      mobileTextContainer,
      mobileReferenceContainer,
      mobileCopyrightContainer
    ].forEach(function (container) {
      if (!container) return;

      container.style.width = textWidth + "px";
    });

    articlePanel.setAttribute("x", "3.889");
    articlePanel.setAttribute("width", String(panelWidth));
  }

  function resizeMobileArticleText() {
    if (
      !mobileTitleContainer ||
      !mobileTextContainer ||
      !mobileReferenceContainer ||
      !mobileCopyrightContainer
    ) return;

    const titleY = 150.82375;
    const gapTitleBody = 18;
    const gapBodyReference = 18;
    const gapReferenceCopyright = 18;

    const titleHeight =
      mobileTitleContainer.getBoundingClientRect().height;

    mobileTitleObject.setAttribute(
      "height",
      String(Math.ceil(titleHeight) + 2)
    );

    const bodyY = titleY + titleHeight + gapTitleBody;

    mobileTextObject.setAttribute("y", String(bodyY));

    const bodyHeight =
      mobileTextContainer.getBoundingClientRect().height;

    mobileTextObject.setAttribute(
      "height",
      String(Math.ceil(bodyHeight) + 2)
    );

    const referenceY =
      bodyY + bodyHeight + gapBodyReference;

    mobileReferenceObject.setAttribute(
      "y",
      String(referenceY)
    );

    const referenceHeight =
      mobileReferenceContainer.getBoundingClientRect().height;

    mobileReferenceObject.setAttribute(
      "height",
      String(Math.ceil(referenceHeight) + 2)
    );

    const copyrightY =
      referenceY + referenceHeight + gapReferenceCopyright;

    mobileCopyrightObject.setAttribute(
      "y",
      String(copyrightY)
    );

    const copyrightHeight =
      mobileCopyrightContainer.getBoundingClientRect().height;

    mobileCopyrightObject.setAttribute(
      "height",
      String(Math.ceil(copyrightHeight) + 2)
    );

    const panelTop = 100.82375;
    const bottomPadding = 24;

    const totalHeight =
      copyrightY + copyrightHeight + bottomPadding - panelTop;

    articlePanel.setAttribute(
      "height",
      String(Math.ceil(totalHeight))
    );

    const articleBottom =
      190 + 100.82375 + Math.ceil(totalHeight) + 30;

    const homeBottom = 2090;

    const svgHeight = Math.max(articleBottom, homeBottom);

    svg.setAttribute(
      "viewBox",
      "0 0 " + currentMobileWidth + " " + svgHeight
    );

    svg.setAttribute("height", String(svgHeight));
    svg.style.height = svgHeight + "px";
  }

  function updateMobileArticleLayout() {
    const width = getAvailableWidth();

    currentMobileWidth = width;

    createMobileArticleText();
    setMobileTextWidth(width);

    svg.setAttribute("width", String(width));

    resizeMobileArticleText();
  }

  function restoreMobileArticleText() {
    [
      mobileTitleObject,
      mobileTextObject,
      mobileReferenceObject,
      mobileCopyrightObject
    ].forEach(function (element) {
      if (element) element.remove();
    });

    mobileTitleObject = null;
    mobileTitleContainer = null;

    mobileTextObject = null;
    mobileTextContainer = null;

    mobileReferenceObject = null;
    mobileReferenceContainer = null;

    mobileCopyrightObject = null;
    mobileCopyrightContainer = null;

    articleTitle.style.display = originalTitleDisplay;
    articleText.style.display = originalTextDisplay;
    articleReference.style.display = originalReferenceDisplay;

    if (articleCopyright) {
      articleCopyright.style.display = originalCopyrightDisplay;
    }

    articlePanel.setAttribute("height", originalArticleHeight);
    articlePanel.setAttribute("width", originalArticleWidth);
    articlePanel.setAttribute("x", originalArticleX);
  }

  // ==========================================================
  // MISE EN PAGE MOBILE
  // ==========================================================

  function mobileLayout() {
    const width = getAvailableWidth();

    currentMobileWidth = width;

    svg.setAttribute("width", String(width));
    svg.setAttribute("viewBox", "0 0 " + width + " 2160");
    svg.setAttribute("preserveAspectRatio", "xMinYMin meet");

    svg.style.width = "100%";
    svg.style.maxWidth = "100%";
    svg.style.minWidth = "0";
    svg.style.height = "2160px";
    svg.style.display = "block";

    // RECTANGLE DU BANDEAU : POSITIONNÉ AVANT LES TEXTES
    if (banner) {
      banner.setAttribute("x", "14.124");
      banner.setAttribute("y", "-173.095");
      banner.setAttribute("width", String(width - 28));
      banner.setAttribute("height", "125");
    }

    move(
      wrappers.bannerRect,
      3 - 3.078,
      1 - -0.765,
      1
    );

    // TITRE DU BANDEAU
    const titleScale = 1.10;
    const titleTargetX = 120;
    const bannerMarginTop = 40;

    let titleTargetY;

    try {
      const bannerTop = getBannerTopInTitleCoordinates();
      titleTargetY = bannerTop + bannerMarginTop;
    } catch (error) {
      titleTargetY = 85;
    }

    move(
      wrappers.title,
      titleTargetX - 208.723 * titleScale,
      titleTargetY - 22.300 * titleScale,
      titleScale
    );

    // LOGO À GAUCHE DU TITRE, CENTRÉ VERTICALEMENT
    if (wrappers.logo && wrappers.title) {
      try {
        const logoBounds = wrappers.logo.getBBox();
        const titleBounds = wrappers.title.getBBox();

        const logoScale = 1;
        const logoGap = 24;

        const titleVisualHeight =
          titleBounds.height * titleScale;

        const logoTargetX =
          titleTargetX -
          logoGap -
          logoBounds.width * logoScale;

        const logoTargetY =
          titleTargetY +
          (titleVisualHeight -
            logoBounds.height * logoScale) / 2;

        move(
          wrappers.logo,
          logoTargetX - logoBounds.x * logoScale,
          logoTargetY - logoBounds.y * logoScale,
          logoScale
        );

      } catch (error) {
        move(wrappers.logo, -18.37, -2.58, 1);
      }
    }

    // SOUS-TITRE ET LIEN HOME
    const subtitleScale = 1.30;
    const subtitleGap = 100;

    if (wrappers.title && wrappers.subtitle) {
      try {
        const titleBounds = wrappers.title.getBBox();
        const subtitleBounds = wrappers.subtitle.getBBox();

        const subtitleTargetX =
          titleTargetX +
          titleBounds.width * titleScale +
          subtitleGap;

        const subtitleTargetY = titleTargetY;

        move(
          wrappers.subtitle,
          subtitleTargetX - subtitleBounds.x * subtitleScale,
          subtitleTargetY - subtitleBounds.y * subtitleScale,
          subtitleScale
        );

        // LIEN HOME : À DROITE DU SOUS-TITRE
        if (wrappers.home) {
          const homeBounds = wrappers.home.getBBox();
          const homeGap = 24;

          const homeTargetX =
            subtitleTargetX +
            subtitleBounds.width * subtitleScale +
            homeGap;

          const homeTargetY =
            subtitleTargetY +
            (subtitleBounds.height * subtitleScale -
              homeBounds.height) / 2;

          move(
            wrappers.home,
            homeTargetX - homeBounds.x,
            homeTargetY - homeBounds.y,
            1
          );
        }

      } catch (error) {
        move(
          wrappers.subtitle,
          120 - 1010.446 * subtitleScale,
          105 - 25.516 * subtitleScale,
          subtitleScale
        );
      }
    }

    // POSITIONNEMENT DE L'ARTICLE
    const articleStart = 190;

    articles.forEach((a, i) => {
      move(
        wrappers[a.id],
        14 - a.x,
        articleStart + i * 468 - a.y,
        1
      );
    });

    createMobileArticleText();
    setMobileTextWidth(width);

    if (resizeFrame) {
      cancelAnimationFrame(resizeFrame);
    }

    resizeFrame = requestAnimationFrame(function () {
      resizeFrame = null;
      updateMobileArticleLayout();
    });
  }

  // ==========================================================
  // RESTAURATION ORDINATEUR
  // ==========================================================

  function desktopLayout() {
    svg.setAttribute("width", original.width);
    svg.setAttribute("height", original.height);
    svg.setAttribute("viewBox", original.viewBox);

    svg.style.width = "";
    svg.style.height = "";
    svg.style.maxWidth = "";
    svg.style.minWidth = "";
    svg.style.display = "";

    Object.values(wrappers).forEach(function (wrapper) {
      if (wrapper) wrapper.removeAttribute("transform");
    });

    restoreRectangle(banner, originalBanner);
    restoreMobileArticleText();

    svg.removeAttribute("preserveAspectRatio");
  }

  // ==========================================================
  // VERROUILLAGE DU MODE MOBILE ET STABILISATION DU CHARGEMENT
  // ==========================================================

  const mobileQuery = window.matchMedia("(max-width: 600px)");
  const mobileAtStart = mobileQuery.matches;

  function refreshMobileLayout() {
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        if (mobileQuery.matches) {
          mobileLayout();
        }
      });
    });
  }

  if (mobileAtStart) {
    mobileLayout();

    window.addEventListener("load", refreshMobileLayout);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(refreshMobileLayout);
    }

    window.addEventListener("resize", refreshMobileLayout);

  } else {
    desktopLayout();

    function onBreakpointChange() {
      if (mobileQuery.matches) {
        mobileLayout();
      } else {
        desktopLayout();
      }
    }

    if (mobileQuery.addEventListener) {
      mobileQuery.addEventListener("change", onBreakpointChange);
    } else {
      mobileQuery.addListener(onBreakpointChange);
    }

    window.addEventListener("resize", function () {
      if (mobileQuery.matches) {
        refreshMobileLayout();
      }
    });
  }
})();
